DROP TABLE IF EXISTS `anggota`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `anggota` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nip` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'NIP — identitas unik, pencocokan form guest',
  `nama` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bidang_id` bigint unsigned NOT NULL,
  `golongan_asn` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `no_hp` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_masuk` date DEFAULT NULL,
  `tpp_mulai_pokok` tinyint DEFAULT NULL COMMENT 'Bulan (1-12) pertama potongan TPP simpanan pokok',
  `tpp_tahun_pokok` smallint DEFAULT NULL COMMENT 'Tahun pertama potongan TPP simpanan pokok',
  `tpp_mulai_wajib` tinyint DEFAULT NULL COMMENT 'Bulan (1-12) pertama potongan TPP simpanan wajib',
  `tpp_tahun_wajib` smallint DEFAULT NULL COMMENT 'Tahun pertama potongan TPP simpanan wajib',
  `tanggal_keluar` date DEFAULT NULL COMMENT 'NULL = masih aktif',
  `is_pendaftar_ulang` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('aktif','nonaktif','pensiun') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'aktif',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `anggota_nip_unique` (`nip`),
  KEY `anggota_bidang_id_foreign` (`bidang_id`),
  KEY `anggota_status_index` (`status`),
  CONSTRAINT `anggota_bidang_id_foreign` FOREIGN KEY (`bidang_id`) REFERENCES `bidang` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=257 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
