CREATE TABLE `void_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ledger_id` bigint unsigned NOT NULL,
  `alasan` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Wajib diisi oleh pemohon',
  `status` enum('menunggu','disetujui','ditolak') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'menunggu',
  `diminta_oleh` bigint unsigned NOT NULL,
  `tanggal_permintaan` datetime NOT NULL,
  `diputuskan_oleh` bigint unsigned DEFAULT NULL,
  `tanggal_keputusan` datetime DEFAULT NULL,
