  `reversal_ledger_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_pending_void` (`ledger_id`,`status`),
  KEY `void_requests_diminta_oleh_foreign` (`diminta_oleh`),
  KEY `void_requests_diputuskan_oleh_foreign` (`diputuskan_oleh`),
  KEY `void_requests_reversal_ledger_id_foreign` (`reversal_ledger_id`),
  KEY `void_requests_status_index` (`status`),
  CONSTRAINT `void_requests_diminta_oleh_foreign` FOREIGN KEY (`diminta_oleh`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `void_requests_diputuskan_oleh_foreign` FOREIGN KEY (`diputuskan_oleh`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `void_requests_ledger_id_foreign` FOREIGN KEY (`ledger_id`) REFERENCES `ledger` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `void_requests_reversal_ledger_id_foreign` FOREIGN KEY (`reversal_ledger_id`) REFERENCES `ledger` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
